bg=3
sources={5:[[1,1,0],[0,1,0],[0,1,1]], 2:[[1,0,0],[0,1,1],[0,0,1]], 6:[[1,1,0],[0,1,0],[1,1,1]], 9:[[1,1,1],[0,1,0],[1,0,1]], 7:[[1,1,0],[1,0,1],[0,1,0]], 4:[[1,0,0],[0,1,1],[1,0,0]]}
layout=[[5,7],[6,9],[4,2]]
out=[[bg]*13 for _ in range(19)]
for br,row in enumerate(layout):
    for bc,color in enumerate(row):
        r0=1+br*6; c0=1+bc*6
        for r in range(5):
            for c in range(5):
                if r in (0,4) or c in (0,4): val=color
                else: val=bg if sources[color][r-1][c-1] else color
                out[r0+r][c0+c]=val
print('\n'.join(' '.join(map(str,r)) for r in out))

sources[7]=[[1,1,1],[1,0,1],[0,1,0]]
out=[[bg]*13 for _ in range(19)]
for br,row in enumerate(layout):
